// #81a5e9 רכיב העלאת מסמכים ותעודות — на экране «הוספת מכרז» (S-09). Файлы только выбираются
// (статус «מוכן להעלאה»), тендер не создаётся — данных не остаётся.
import { test, expect, Page } from '@playwright/test';
import { authState, dropFiles, qaFile, qaName, uploadItem } from '../helpers/tenderflow';

test.use({ storageState: authState('admin') });

const FILES_LABEL = 'קבצי המכרז (אפשר לבחור כמה קבצים)';

async function openManualUpload(page: Page) {
  await page.goto('/tenders/new');
  await page.getByLabel('העלאת קבצים').check();
  await page.getByRole('button', { name: 'המשך בהעלאה ידנית' }).click();
  const input = page.getByLabel(FILES_LABEL, { exact: true });
  await expect(input).toBeAttached();
  return input;
}

test.describe('רכיב העלאת מסמכים — הוספת מכרז', () => {
  test('בחירת כמה קבצים בבת אחת והסרת קובץ #81a5e9 @desktop @prod-safe', async ({ page }) => {
    const input = await openManualUpload(page);
    const base = qaName('upl');
    const files = [qaFile(`${base}-1`, 'pdf'), qaFile(`${base}-2`, 'pdf'), qaFile(`${base}-3`, 'docx')];

    await input.setInputFiles(files);

    // Т8: несколько файлов за раз; Т3: имя каждого файла видно
    for (const f of files) await expect(uploadItem(page, f.name).getByRole('status')).toHaveText('מוכן להעלאה');

    // Т7: удаление файла из списка
    await page.getByRole('button', { name: `הסרה: ${files[1].name}` }).click();
    await expect(uploadItem(page, files[1].name)).toHaveCount(0);
    await expect(uploadItem(page, files[0].name)).toBeVisible();
    await expect(uploadItem(page, files[2].name)).toBeVisible();
  });

  test('קובץ מסוג שאינו נתמך נדחה עם הודעה #81a5e9 @desktop @prod-safe', async ({ page }) => {
    const input = await openManualUpload(page);
    const base = qaName('upl');
    const exe = qaFile(`${base}-bad`, 'exe');
    const pdf = qaFile(`${base}-ok`, 'pdf');

    await input.setInputFiles([exe, pdf]);

    // Т9: неподдерживаемый тип отклонён с сообщением; поддерживаемый из той же пачки принят
    await expect(page.getByRole('alert').filter({ hasText: `סוג הקובץ ${exe.name} אינו נתמך` })).toBeVisible();
    await expect(uploadItem(page, exe.name)).toHaveCount(0);
    await expect(uploadItem(page, pdf.name).getByRole('status')).toHaveText('מוכן להעלאה');
  });

  test('קובץ ריק (0 בייט) נדחה עם הודעה #81a5e9 @desktop @prod-safe', async ({ page }) => {
    const input = await openManualUpload(page);
    const empty = qaFile(qaName('upl-empty'), 'pdf', { empty: true });

    await input.setInputFiles(empty);

    await expect(page.getByRole('alert').filter({ hasText: `הקובץ ${empty.name} ריק` })).toBeVisible();
    await expect(uploadItem(page, empty.name)).toHaveCount(0);
  });

  test('גרירה ושחרור של קובץ לאזור ההעלאה #81a5e9 @desktop @prod-safe', async ({ page }) => {
    const input = await openManualUpload(page);
    await expect(page.getByText('אפשר גם לגרור קבצים לכאן.')).toBeVisible();
    const name = `${qaName('upl-drop')}.pdf`;

    // Т2: перетаскивание (синтетический drop с DataTransfer)
    await dropFiles(page, input, [{ name, mimeType: 'application/pdf', content: '%PDF-1.4\n%QA-AUTO\n%%EOF\n' }]);

    await expect(uploadItem(page, name).getByRole('status')).toHaveText('מוכן להעלאה');
  });
});
